var t=`0203-salmorejo`;var a=`world-0203`;var o=`ES`;var n=`southern-europe`;var r=4;var s=84;var l={en:`Salmorejo`,ua:`Сальморехо`};var d={en:`A traditional Spain dish made with tomato, garlic, white bread, chicken egg. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Іспанія. Основні інгредієнти: помідор, часник, білий хліб, куряче яйце. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var h=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:6,i:[[`tomato`,950,`g`],[`garlic`,1,`clove`]]},{en:`Blend the tomatoes with the day-old bread and garlic; emulsify the olive oil into a very thick, creamy soup, then salt to taste.`,ua:`Збийте помідори з черствим хлібом і часником, поступово введіть оливкову олію до густого кремоподібного супу; посоліть.`,t:[`mixing`],m:6,i:[[`white-bread`,190,`g`],[`extra-virgin-olive-oil`,95,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 60 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 60 хвилин.`,t:[`rapid-chilling`],m:60,i:[]},{en:`Boil the eggs for about 9 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 9 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:9,i:[[`chicken-egg`,2,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`serrano-ham`,85,`g`]]}];var g={slug:t,id:a,country:`ES`,region:n,servings:4,minutes:84,title:l,text:d,steps:h};export{o as country,g as default,a as id,s as minutes,n as region,r as servings,t as slug,h as steps,d as text,l as title};